package com.vynedam.stockai.service; import com.vynedam.stockai.domain.BatchStatus; import com.vynedam.stockai.repository.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class ReorderService{private final MaterialRepository materials;private final BatchRepository batches;public ReorderService(MaterialRepository m,BatchRepository b){materials=m;batches=b;}public List<Map<String,Object>>recommendations(){var stock=new HashMap<String,Double>();batches.findByStatus(BatchStatus.AVAILABLE).forEach(b->stock.merge(b.materialId,b.quantity,Double::sum));return materials.findAll().stream().filter(m->stock.getOrDefault(m.id,0d)<=m.reorderPoint).map(m->Map.<String,Object>of("materialId",m.id,"sku",m.sku,"name",m.name,"availableQuantity",stock.getOrDefault(m.id,0d),"reorderPoint",m.reorderPoint,"suggestedQuantity",Math.max(m.reorderPoint*2-stock.getOrDefault(m.id,0d),m.reorderPoint),"alert","LOW_STOCK")).toList();}}
